<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Marrow — Pricing</title>
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
      background: #ffffff;
      color: #1a1a1a;
      line-height: 1.6;
    }

    .pricing-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 80px 24px;
    }

    .section-header {
      text-align: center;
      margin-bottom: 64px;
    }

    .section-header h1 {
      font-size: 48px;
      font-weight: 700;
      letter-spacing: -1px;
      margin-bottom: 16px;
      color: #1a1a1a;
    }

    .section-header p {
      font-size: 18px;
      color: #6b7280;
      max-width: 500px;
      margin: 0 auto;
    }

    .cards-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 24px;
      align-items: stretch;
    }

    .pricing-card {
      background: #ffffff;
      border: 1px solid #e5e7eb;
      border-radius: 12px;
      padding: 32px;
      display: flex;
      flex-direction: column;
      position: relative;
      transition: all 0.3s ease;
    }

    .pricing-card:hover {
      border-color: #d1d5db;
    }

    @media (prefers-reduced-motion: reduce) {
      .pricing-card {
        transition: none;
      }
    }

    /* Team card elevation */
    .pricing-card.featured {
      transform: translateY(-12px);
      box-shadow: 0 20px 40px rgba(6, 182, 212, 0.15);
      border: 2px solid #06b6d4;
      background: linear-gradient(135deg, #ffffff 0%, #f0f9fc 100%);
    }

    .pricing-card.featured:hover {
      box-shadow: 0 24px 48px rgba(6, 182, 212, 0.2);
      border-color: #0891b2;
    }

    .tier-badge {
      position: absolute;
      top: -12px;
      left: 32px;
      background: #06b6d4;
      color: white;
      padding: 4px 12px;
      border-radius: 20px;
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.5px;
      text-transform: uppercase;
      z-index: 10;
    }

    .tier-name {
      font-size: 20px;
      font-weight: 700;
      margin-top: 16px;
      margin-bottom: 16px;
      color: #1a1a1a;
    }

    .pricing-display {
      margin-bottom: 28px;
    }

    .price {
      font-size: 36px;
      font-weight: 700;
      color: #06b6d4;
      margin-bottom: 4px;
    }

    .price-unit {
      font-size: 14px;
      color: #6b7280;
      font-weight: 500;
    }

    .features-list {
      flex: 1;
      margin-bottom: 28px;
    }

    .features-list ul {
      list-style: none;
    }

    .features-list li {
      font-size: 14px;
      padding: 10px 0;
      color: #374151;
      display: flex;
      align-items: flex-start;
    }

    .features-list li::before {
      content: '✓';
      color: #06b6d4;
      font-weight: 700;
      margin-right: 10px;
      flex-shrink: 0;
    }

    .cta-button {
      padding: 12px 24px;
      border: 2px solid #06b6d4;
      background: white;
      color: #06b6d4;
      border-radius: 6px;
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      text-align: center;
      text-decoration: none;
      display: inline-block;
      transition: all 0.3s ease;
      width: 100%;
      letter-spacing: 0.3px;
    }

    .cta-button:hover {
      background: #06b6d4;
      color: white;
      border-color: #06b6d4;
    }

    .cta-button:focus {
      outline: 2px solid #0891b2;
      outline-offset: 2px;
    }

    @media (prefers-reduced-motion: reduce) {
      .cta-button {
        transition: none;
      }
    }

    .pricing-card.featured .cta-button {
      background: #06b6d4;
      color: white;
      border-color: #06b6d4;
    }

    .pricing-card.featured .cta-button:hover {
      background: #0891b2;
      border-color: #0891b2;
    }

    /* Responsive grid */
    @media (max-width: 768px) {
      .pricing-container {
        padding: 60px 20px;
      }

      .section-header h1 {
        font-size: 36px;
      }

      .section-header p {
        font-size: 16px;
      }

      .pricing-card {
        padding: 24px;
      }

      .pricing-card.featured {
        transform: translateY(-8px);
      }

      .cards-grid {
        grid-template-columns: 1fr;
        gap: 20px;
      }
    }

    /* Ensure proper stacking for featured card on mobile */
    @media (max-width: 640px) {
      .cards-grid {
        grid-template-columns: 1fr;
      }

      .pricing-card.featured {
        transform: translateY(0);
      }
    }
  </style>
</head>
<body>
  <section class="pricing-container">
    <div class="section-header">
      <h1>Pricing</h1>
      <p>Start free. Upgrade when your team does.</p>
    </div>

    <div class="cards-grid">
      <!-- Solo Tier -->
      <div class="pricing-card">
        <div class="tier-name">Solo</div>
        <div class="pricing-display">
          <div class="price">$0</div>
          <div class="price-unit">forever</div>
        </div>
        <div class="features-list">
          <ul>
            <li>1 developer</li>
            <li>Local test maps</li>
            <li>Community support</li>
          </ul>
        </div>
        <button class="cta-button">Start free</button>
      </div>

      <!-- Team Tier (Recommended) -->
      <div class="pricing-card featured">
        <div class="tier-badge">Recommended</div>
        <div class="tier-name">Team</div>
        <div class="pricing-display">
          <div class="price">$12</div>
          <div class="price-unit">per user / month</div>
        </div>
        <div class="features-list">
          <ul>
            <li>Everything in Solo</li>
            <li>Shared team maps</li>
            <li>CI integration</li>
            <li>Email support</li>
          </ul>
        </div>
        <button class="cta-button">Start 14-day trial</button>
      </div>

      <!-- Enterprise Tier -->
      <div class="pricing-card">
        <div class="tier-name">Enterprise</div>
        <div class="pricing-display">
          <div class="price">Custom</div>
          <div class="price-unit">pricing for your needs</div>
        </div>
        <div class="features-list">
          <ul>
            <li>Everything in Team</li>
            <li>SSO / SAML</li>
            <li>Self-hosted option</li>
            <li>Dedicated support</li>
          </ul>
        </div>
        <button class="cta-button">Contact sales</button>
      </div>
    </div>
  </section>
</body>
</html>
